<?php
namespace App\Http\Controllers;
use App\Models\{SeoCampaign, SeoCompetitor, SeoKeyword};
use Illuminate\Http\Request;
use Illuminate\Support\Facades\DB;
use Illuminate\Validation\Rule;
use PhpOffice\PhpSpreadsheet\IOFactory;
use PhpOffice\PhpSpreadsheet\Spreadsheet;
use PhpOffice\PhpSpreadsheet\Writer\Xlsx;

class SeoKeywordController extends Controller
{
 public function index(SeoCampaign $campaign, Request $request){$this->authorize('view',$campaign);$keywords=$campaign->keywords()->with(['rankings'=>fn($q)=>$q->latest('checked_on')])->latest()->get();return view('seo.keywords.index',compact('campaign','keywords'));}
 public function store(Request $request, SeoCampaign $campaign){$this->authorize('contribute',$campaign);$d=$request->validate(['keyword'=>'required|string|max:255','target_page_url'=>'nullable|url|max:2048','category'=>'nullable|string|max:100','location'=>'nullable|string|max:150','device'=>['required',Rule::in(['desktop','mobile'])],'search_volume'=>'nullable|integer|min:0','keyword_difficulty'=>'nullable|numeric|min:0|max:100','initial_rank_position'=>'nullable|integer|min:1|max:10000','initial_checked_on'=>'nullable|date']);$initialRank=$d['initial_rank_position'] ?? null;$initialCheckedOn=$d['initial_checked_on'] ?? now()->toDateString();unset($d['initial_rank_position'],$d['initial_checked_on']);$d += ['normalized_keyword'=>mb_strtolower(trim(preg_replace('/\s+/', ' ', $d['keyword']))),'language'=>'en','search_engine'=>'google','priority'=>'medium','created_by'=>auth()->id()];$existing=$campaign->keywords()->withTrashed()->where(['normalized_keyword'=>$d['normalized_keyword'],'location'=>$d['location'] ?? null,'device'=>$d['device'],'search_engine'=>$d['search_engine']])->first();if($existing && ! $existing->trashed())return back()->withInput()->with('error','This keyword already exists for the selected location and device. Use Update to save its latest ranking.');if($existing)$existing->forceDelete();$keyword=$campaign->keywords()->create($d);if(!is_null($initialRank)){$keyword->rankings()->updateOrCreate(['checked_on'=>$initialCheckedOn,'source'=>'manual'],['rank_position'=>$initialRank,'recorded_by'=>auth()->id()]);}return back()->with('success',$existing ? 'Old deleted keyword removed and a new keyword saved.' : ($initialRank ? 'Keyword and initial ranking saved.' : 'Keyword added. Use Update to add its first ranking snapshot.'));}
 public function destroy(SeoCampaign $campaign, SeoKeyword $keyword){$this->authorize('contribute',$campaign);abort_unless($keyword->seo_campaign_id===$campaign->id,404);$keyword->forceDelete();return back()->with('success','Keyword permanently deleted.');}
 public function downloadTemplate(SeoCampaign $campaign){$this->authorize('contribute',$campaign);$sheet=(new Spreadsheet())->getActiveSheet();$sheet->fromArray(['Keyword','Target URL','Location','Initial Rank','Checked On'],null,'A1');$sheet->fromArray([['Moulded cord manufacturer in Mumbai','https://example.com/moulded-cords','Mumbai',24,now()->toDateString()],['Cable manufacturer in Mumbai','https://example.com/cables','Mumbai',null,now()->toDateString()]],null,'A2');foreach(['A'=>38,'B'=>48,'C'=>22,'D'=>16,'E'=>16] as $column=>$width)$sheet->getColumnDimension($column)->setWidth($width);$sheet->getStyle('A1:E1')->getFont()->setBold(true);return response()->streamDownload(function() use($sheet){(new Xlsx($sheet->getParent()))->save('php://output');},'seo-keyword-import-template.xlsx',['Content-Type'=>'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet']);}
 public function import(Request $request, SeoCampaign $campaign){$this->authorize('contribute',$campaign);$request->validate(['file'=>'required|file|mimes:xlsx,xls|max:5120']);try{$rows=IOFactory::load($request->file('file')->getRealPath())->getActiveSheet()->toArray(null,true,true,false);}catch(\Throwable $e){return back()->with('error','The uploaded Excel file could not be read.');}$headers=array_map(fn($value)=>strtolower(trim((string)$value)),$rows[0]??[]);$expected=['keyword','target url','location','initial rank','checked on'];if($headers!==$expected)return back()->with('error','Invalid template headers. Download and use the provided Excel template.');$created=0;$skipped=0;$errors=[];DB::transaction(function() use($rows,$campaign,&$created,&$skipped,&$errors){foreach(array_slice($rows,1) as $index=>$row){$line=$index+2;$keyword=trim((string)($row[0]??''));if($keyword==='')continue;$targetUrl=trim((string)($row[1]??''));$location=trim((string)($row[2]??''));$rank=($row[3]??'')===''?null:$row[3];$checkedOn=$row[4]??null;if($targetUrl!==''&&!filter_var($targetUrl,FILTER_VALIDATE_URL)){$errors[]="Row {$line}: Target URL is invalid.";continue;}if(!is_null($rank)&&(!is_numeric($rank)||(int)$rank<1)){$errors[]="Row {$line}: Initial Rank must be a positive number.";continue;}if(is_numeric($checkedOn))$checkedOn=\PhpOffice\PhpSpreadsheet\Shared\Date::excelToDateTimeObject($checkedOn)->format('Y-m-d');elseif($checkedOn) $checkedOn=date('Y-m-d',strtotime((string)$checkedOn));else $checkedOn=now()->toDateString();if(!$checkedOn||$checkedOn==='1970-01-01'){$errors[]="Row {$line}: Checked On date is invalid.";continue;}$normalized=mb_strtolower(trim(preg_replace('/\s+/', ' ', $keyword)));$existing=$campaign->keywords()->withTrashed()->where(['normalized_keyword'=>$normalized,'location'=>$location?:null,'device'=>'desktop','search_engine'=>'google'])->first();if($existing&&!$existing->trashed()){$skipped++;continue;}if($existing)$existing->forceDelete();$newKeyword=$campaign->keywords()->create(['keyword'=>$keyword,'normalized_keyword'=>$normalized,'target_page_url'=>$targetUrl?:null,'location'=>$location?:null,'device'=>'desktop','priority'=>'medium','language'=>'en','search_engine'=>'google','created_by'=>auth()->id()]);if(!is_null($rank))$newKeyword->rankings()->create(['checked_on'=>$checkedOn,'rank_position'=>(int)$rank,'source'=>'Excel import','recorded_by'=>auth()->id()]);$created++;}});if($errors)return back()->with('error',implode(' ',array_slice($errors,0,5)));return back()->with('success',"{$created} keyword(s) imported successfully".($skipped?"; {$skipped} duplicate row(s) skipped.":'.'));}
 public function addRanking(Request $request, SeoCampaign $campaign, SeoKeyword $keyword){$this->authorize('contribute',$campaign);abort_unless($keyword->seo_campaign_id===$campaign->id,404);$d=$request->validate(['checked_on'=>'required|date','rank_position'=>'nullable|integer|min:1|max:10000','source'=>'required|string|max:100','remarks'=>'nullable|string|max:2000']);$keyword->rankings()->updateOrCreate(['checked_on'=>$d['checked_on'],'source'=>$d['source']],$d+['recorded_by'=>auth()->id()]);return back()->with('success','Ranking snapshot saved.');}
 public function competitors(SeoCampaign $campaign){$this->authorize('view',$campaign);return view('seo.competitors.index',['campaign'=>$campaign,'competitors'=>$campaign->competitors()->latest()->get()]);}
 public function storeCompetitor(Request $request, SeoCampaign $campaign){$this->authorize('contribute',$campaign);$d=$request->validate(['name'=>'required|string|max:255','website_url'=>'required|url|max:512','services'=>'nullable|string|max:3000','strengths'=>'nullable|string|max:3000','weaknesses'=>'nullable|string|max:3000','opportunities'=>'nullable|string|max:3000','notes'=>'nullable|string|max:3000','data_source'=>'nullable|string|max:100']);$campaign->competitors()->create($d+['created_by'=>auth()->id()]);return back()->with('success','Competitor added. Third-party estimates must include their data source.');}
}
